// Live values — press the buttons above, then re-run to see the effect.
const val = (k) => ({ value: nb.get(k), type: typeof nb.get(k) });
return {
  count:     val('count'),      // increment: goes up by 1 each press
  flag:      val('flag'),       // toggle: true/false
  fruit:     val('fruit'),      // set value: '(none)' → 'apple'
  last_ping: val('last_ping'),  // set-with-no-value: a fresh timestamp each press
};

// Demonstrate the batch reset from code too: nb.set works from a JS cell
// exactly like a button's set:{…}. (This is what "Reset all" does internally.)
nb.set('count', 0);
nb.set('flag', false);
nb.set('fruit', '(none)');
console.log('reset count/flag/fruit — the readouts above should now show 0 / false / (none)');
return { count: nb.get('count'), flag: nb.get('flag'), fruit: nb.get('fruit') };
